{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.mikusnuz/app-publish",
  "description": "MCP server for App Store Connect & Google Play Console — iOS/Android app management",
  "repository": {
    "url": "https://github.com/mikusnuz/app-publish-mcp",
    "source": "github"
  },
  "version": "0.3.1",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "app-publish-mcp",
      "version": "0.3.1",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "APPLE_KEY_ID",
          "description": "Apple App Store Connect API Key ID",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "APPLE_ISSUER_ID",
          "description": "Apple App Store Connect Issuer ID",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "APPLE_P8_PATH",
          "description": "Path to Apple AuthKey .p8 file",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "GOOGLE_SERVICE_ACCOUNT_PATH",
          "description": "Path to Google Play service account JSON key file",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        }
      ]
    }
  ]
}
